//! Comparator contracts, not Ares slicing passes. Real records come from the
//! runtime classic stream; absent arc/multi-object streams below are synthetic.
//! Orca 8500fcd: GCode::do_export (config/statistics/object boundaries),
//! GCodeWriter::{travel_to_xy,travel_to_z,extrude_to_xy,extrude_arc_to_xy,
//! set_acceleration,set_temperature,set_fan,retract}, GCodeProcessor::run_post_process.
use super::compare_ordered_bytes_generator_only as compare;

const ORCA: &str = "; generated by OrcaSlicer 2.5.0 on 2026-09-08 at 04:26:03\n";
const ARES: &str = concat!(
    "; generated by Ares ",
    env!("CARGO_PKG_VERSION"),
    " on 1980-01-01 at 00:00:00\n"
);

fn reject(reference: &str, baseline: &str, changed: &str, label: &str) {
    assert_ne!(baseline, changed, "mutation missed: {label}");
    let error = compare(reference.as_bytes(), changed.as_bytes()).unwrap_err();
    assert!(
        error.contains("first difference at byte"),
        "{label}: {error}"
    );
}

pub(crate) fn mutations(reference: &str, first: &str, second: &str, changed: &str, label: &str) {
    // Header substitution constructs only a comparator input, never an Orca replay.
    super::normalize_one_generator_line(reference.as_bytes(), super::GeneratorKind::Orca).unwrap();
    let generator = reference
        .split_inclusive('\n')
        .find(|line| line.starts_with("; generated by OrcaSlicer "))
        .unwrap();
    assert_eq!(reference.matches(generator).count(), 1);
    let baseline = reference.replacen(generator, ARES, 1);
    compare(reference.as_bytes(), baseline.as_bytes()).unwrap();
    let lines: Vec<_> = baseline.split_inclusive('\n').collect();
    let i = lines.iter().position(|line| *line == first).unwrap();
    let j = lines.iter().position(|line| *line == second).unwrap();
    assert!(i < j, "ordered distinct anchors: {label}");
    assert_ne!(first, second);
    assert_ne!(first, changed);
    let mut replacement = lines.clone();
    replacement[i] = changed;
    reject(
        reference,
        &baseline,
        &replacement.concat(),
        &format!("{label}/change"),
    );
    let mut deletion = lines.clone();
    deletion.remove(i);
    assert_eq!(deletion.len() + 1, lines.len());
    reject(
        reference,
        &baseline,
        &deletion.concat(),
        &format!("{label}/delete"),
    );
    let mut reordered = lines;
    reordered.swap(i, j);
    assert_eq!((reordered[i], reordered[j]), (second, first));
    reject(
        reference,
        &baseline,
        &reordered.concat(),
        &format!("{label}/reorder"),
    );
}

#[test]
fn gcode_writer_arcs_and_do_export_multiobject_reject_six_synthetic_mutations() {
    // Classic has neither arcs nor multiple objects. These are comparator-only
    // snippets, not independently captured reference artifacts or producer passes.
    let arcs = format!("{ORCA}G2 X10 Y20 I1 J2 E.5 F3000\nG3 X30 Y40 R5 E.6\n");
    mutations(
        &arcs,
        "G2 X10 Y20 I1 J2 E.5 F3000\n",
        "G3 X30 Y40 R5 E.6\n",
        "G3 X10 Y20 I1 J2 E.5 F3000\n",
        "synthetic arcs",
    );
    let objects = format!(
        "{ORCA}; printing object alpha id:10 copy 0\n; stop printing object alpha id:10 copy 0\n; printing object beta id:20 copy 0\n; stop printing object beta id:20 copy 0\n"
    );
    mutations(
        &objects,
        "; printing object alpha id:10 copy 0\n",
        "; printing object beta id:20 copy 0\n",
        "; printing object alpha id:20 copy 0\n",
        "synthetic object identity",
    );
}

#[test]
fn generator_contract_validates_each_producer_and_exact_final_version() {
    let reference = format!("{ORCA}G1 X1\n");
    let actual = format!("{ARES}G1 X1\n");
    compare(reference.as_bytes(), actual.as_bytes()).unwrap();
    for (header, expected_name, version) in [
        (ORCA, "OrcaSlicer", "2.5.0"),
        (ARES, "Ares", env!("CARGO_PKG_VERSION")),
    ] {
        let invalid = [
            "G1 X1\n".as_bytes().to_vec(),
            format!("{header}{header}G1 X1\n").into_bytes(),
            format!("{}G1 X1\n", if header == ORCA { ARES } else { ORCA }).into_bytes(),
            format!("{}G1 X1\n", header.replace(version, "2.4.2")).into_bytes(),
            format!(
                "{}G1 X1\n",
                header.replace(version, &format!("{version}-beta"))
            )
            .into_bytes(),
            format!(
                "{}G1 X1\n",
                header.replace(version, &format!("{version}-rc"))
            )
            .into_bytes(),
            format!(
                "{}G1 X1\n",
                header.replace(version, &version.replace('.', "x"))
            )
            .into_bytes(),
            format!(
                "{}G1 X1\n",
                if header == ORCA {
                    header.replace(" at ", " ")
                } else {
                    header.replace(" on ", " on 2030-12-31 at 23:59:58 on ")
                }
            )
            .into_bytes(),
            format!("prefix {header}G1 X1\n").into_bytes(),
            [header.as_bytes(), &[0xff]].concat(),
        ];
        for bytes in invalid {
            let error = if header == ORCA {
                assert_ne!(bytes, reference.as_bytes());
                compare(&bytes, actual.as_bytes())
            } else {
                assert_ne!(bytes, actual.as_bytes());
                compare(reference.as_bytes(), &bytes)
            }
            .unwrap_err();
            assert!(
                error.contains(expected_name) || error.contains("utf-8"),
                "{error}"
            );
        }
    }
}

#[test]
fn generator_contract_accepts_only_fixed_dos_epoch_for_ares() {
    let reference = format!("{ORCA}G1 X1\n");
    let actual = format!("{ARES}G1 X1\n");
    compare(reference.as_bytes(), actual.as_bytes()).unwrap();
    for header in [
        concat!("; generated by Ares ", env!("CARGO_PKG_VERSION"), "\n").to_owned(),
        ARES.replace("1980-01-01", "2030-12-31"),
        ARES.replace("1980", "1981"),
        ARES.replace("01-01", "00-01"),
        ARES.replace("01-01", "01-00"),
        ARES.replace("01-01", "02-01"),
        ARES.replace("01-01", "01-02"),
        ARES.replace("01-01", "1-1"),
        ARES.replace("00:00:00", "01:00:00"),
        ARES.replace("00:00:00", "00:01:00"),
        ARES.replace("00:00:00", "00:00:01"),
        ARES.replace(" at ", " "),
        ARES.replace("00:00:00", "00:00:00 UTC"),
    ] {
        assert_ne!(header, ARES);
        assert!(compare(reference.as_bytes(), format!("{header}G1 X1\n").as_bytes()).is_err());
    }
}

#[test]
fn do_export_preserves_six_stream_boundaries() {
    let reference = format!("{ORCA}G1 X1 Y2\n");
    let baseline = format!("{ARES}G1 X1 Y2\n");
    for body in [
        "G1  X1 Y2\n",
        "G1 X1 Y2\r\n",
        "G1 X1 Y2",
        "G1 X1 Y2\n\n",
        "G1 X1 Y2\nx",
        "G1 X1",
    ] {
        reject(
            &reference,
            &baseline,
            &format!("{ARES}{body}"),
            "stream boundary",
        );
    }
}
